steps.solution:
import numpy as np


def count_in_range(a, lo, hi):
    a = np.asarray(a)
    return int(np.sum((a >= lo) & (a <= hi)))


def zero_negatives(a):
    return np.where(np.asarray(a) < 0, 0, a)


def column_means(M):
    return np.asarray(M, dtype=float).mean(axis=0)
